<?php
declare(strict_types=1);
function student_calibration_editor(?array $editing,string $error,string $csrf,array $draft=[]):void {
  $isEditing=$editing!==null;
  $data=$editing??[];
  if($error!==''&&$draft)foreach(['label','film','developer','preparation','temperature','prebath','white_time','notes'] as $key){
    if(isset($draft[$key])&&is_scalar($draft[$key]))$data[$key]=substr((string)$draft[$key],0,2000);
  }
?>
<div data-student-editor class="student-long-editor">
<div class="student-create-dialog-head"><div><p class="student-kicker"><?=$isEditing?'Edição':'Nova referência'?></p><h2><?=$isEditing?'Editar calibração':'Registrar calibração'?></h2></div><a class="button button-secondary button-compact" href="/aluno/calibracao.php" data-student-editor-close>Fechar</a></div><?php if($error!==''):?><p class="ui-alert ui-alert-error student-long-editor-error" role="alert" tabindex="-1" data-student-editor-error-focus><?=h($error)?></p><?php endif;?><section class="student-tool-workspace"><form method="post" action="/aluno/calibracao.php?<?=$isEditing?'editar='.(int)$editing['id']:'novo=1'?>" class="student-form-grid" data-student-local-form data-local-refresh="calibrations-list" data-local-success="close-dialog"><input type="hidden" name="_csrf" value="<?=h($csrf)?>"><?php if($isEditing):?><input type="hidden" name="id" value="<?=(int)$data['id']?>"><?php endif;?><label class="form-field student-span-2">Nome da referência<input name="label" required placeholder="Ex.: HR-U · Parodinal · 26 °C" value="<?=h((string)($data['label']??''))?>"></label><label class="form-field">Filme<input name="film" value="<?=h((string)($data['film']??''))?>"></label><label class="form-field">Revelador<input name="developer" value="<?=h((string)($data['developer']??''))?>"></label><label class="form-field">Preparo ou diluição<input name="preparation" value="<?=h((string)($data['preparation']??''))?>"></label><label class="form-field">Temperatura<input name="temperature" value="<?=h((string)($data['temperature']??''))?>"></label><label class="form-field">Pré-banho<input name="prebath" value="<?=h((string)($data['prebath']??''))?>"></label><label class="form-field">Tempo do branco<input name="white_time" required value="<?=h((string)($data['white_time']??''))?>"></label><details class="student-optional-fields student-span-2"<?=trim((string)($data['notes']??''))!==''?' open':''?>><summary>Anotações</summary><label class="form-field"><textarea name="notes" rows="3" aria-label="Anotações da calibração"><?=h((string)($data['notes']??''))?></textarea></label></details><div class="student-actions student-span-2"><button class="button button-primary" type="submit"><?=$isEditing?'Salvar alterações':'Salvar referência'?></button><a class="button button-secondary" href="/aluno/calibracao.php" data-student-editor-close>Cancelar</a></div></form></section>
</div>
<?php }
